INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1255, 'koKR', 'Muszę poczynić niezbędne przygotowania, zanim rozpocznie się rytuał przebudzenia. Musicie mnie chronić!', '', 0),
(1256, 'koKR', 'Te jaskinie były niegdyś świątynią nadziei na odrodzenie Pustkowi. Teraz to korytarze koszmarów.', '', 0),
(1257, 'koKR', 'Chodźcie. Musimy iść dalej. Wiele jest do zrobienia, zanim zdołamy wyrwać Naraleksa z jego koszmaru.', '', 0),
(1258, 'koKR', 'W tym ognistym kręgu muszę rzucić zaklęcie, które przepędzi duchy zabitych Władców Kła.', '', 0),
(1259, 'koKR', 'Jaskinie zostały oczyszczone. Ruszajmy do komnaty Naraleksa!', '', 0),
(1263, 'koKR', 'Za tym korytarzem Naralex śpi niespokojnym snem. Chodźmy go obudzić, zanim będzie za późno.', '', 0),
(1264, 'koKR', 'Chrońcie mnie, dzielni wojownicy, gdy zagłębię się w Szmaragdowy Sen, by ocalić Naraleksa i położyć kres temu zepsuciu!', '', 0),
(1265, 'koKR', '%s rozpoczyna rytuał przebudzenia Naraleksa.', '', 0),
(1267, 'koKR', 'Nareszcie! Naralex budzi się z koszmaru.', '', 0),
(1268, 'koKR', '%s rzuca się niespokojnie we śnie.', '', 0),
(1269, 'koKR', '%s wije się w męczarniach. Wygląda na to, że Uczniowi udaje się do niego przebić.', '', 0),
(1270, 'koKR', '%s śni straszliwą wizję. Coś porusza się pod mętną wodą.', '', 0),
(1271, 'koKR', 'NARESZCIE SIĘ OBUDZIŁEM!', '', 0),
(1272, 'koKR', 'Ach, wyrwany z tego straszliwego koszmaru! Dziękuję ci, mój wierny uczniu, i twoim dzielnym towarzyszom.', '', 0),
(1273, 'koKR', 'Atak! Pomóżcie mi pozbyć się $n!', '', 0),
(1274, 'koKR', 'Zajmijcie się $n! Muszę przygotować przebudzenie Naraleksa!', '', 0),
(1276, 'koKR', '$n to bez wątpienia sługa z koszmaru Naraleksa!', '', 0),
(2101, 'koKR', 'Nareszcie! Naraleksa można obudzić! Pomóżcie mi, dzielni poszukiwacze przygód!', '', 0),
(2103, 'koKR', 'Musimy dołączyć do pozostałych uczniów. Wiele jest do zrobienia, zanim podejmę kolejną próbę odrodzenia Pustkowi. Żegnajcie, dzielni wojownicy!', '', 0),
(2660, 'koKR', 'Naralex znów śpi!$b$bDawno temu Naralex przybył do tej jaskini w szlachetnym celu – chciał wkroczyć do Szmaragdowego Snu i przemienić Pustkowia w bujny las. Jego skupienie jednak osłabło, a myśli skaziły wężowe wizje.$b$bTeraz gadzie bestie przenikają z jego snów do tego świata. Trzeba go wyrwać z koszmaru, bo inaczej przepadnie na zawsze, a na świat wyzwolone zostanie wielkie zło.$b$bDopiero gdy jego spaczeni słudzy, Władcy Kła, zginą, będę mógł odprawić rytuał przebudzenia.\n', '', 0),
(2662, 'koKR', 'Zaczynajmy!', 'Zaczynajmy!', 0),
(6094, 'koKR', 'Nigdy nie obudzicie śniącego!', '', 0),
(6095, 'koKR', 'Sploty śmierci was zmiażdżą!', '', 0),
(6096, 'koKR', 'Jestem królem węży! Wszystko mi wolno!', '', 0),
(6097, 'koKR', '', 'Nikt nie ostoi się przed Wężowymi Władcami!', 0);
